const {chromium}=require('playwright');
const path=require('node:path'),fs=require('node:fs'),assert=require('node:assert/strict');
const {ws:WS}=require(path.join(path.dirname(require.resolve('playwright-core/package.json')),'lib/utilsBundle.js'));
(async()=>{
 const endpoint=process.argv[2],fixture=JSON.parse(process.argv[3]);
 const bindings=JSON.parse(fs.readFileSync(process.env.TEAMX_ENVIRONMENT_CONFIG,'utf8')).bindings;
 const config=bindings.find(binding=>binding.environment).environment;
 const headers=Object.fromEntries((config.headers||[]).map(h=>[h.name,h.value]));
 const info=await (await fetch(config.base_url+'/v1/browser/info',{headers})).json();
 const socketURL=new URL(new URL(info.data.cdp_url).pathname,config.base_url);socketURL.protocol=socketURL.protocol==='https:'?'wss:':'ws:';
 const socket=new WS(socketURL,{headers});
 await new Promise((resolve,reject)=>{socket.once('open',resolve);socket.once('error',reject);});
 let serial=0;const pending=new Map();
 socket.on('message',raw=>{const m=JSON.parse(raw);const p=pending.get(m.id);if(p){clearTimeout(p.timer);pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);}});
 const call=(method,params={},sessionId)=>new Promise((resolve,reject)=>{const id=++serial;const timer=setTimeout(()=>{pending.delete(id);reject(Error('CDP observation timed out'));},10000);pending.set(id,{resolve,reject,timer});socket.send(JSON.stringify({id,method,params,sessionId}));});
 const {targetId}=await call('Target.createTarget',{url:fixture.fixture_url});
 const {sessionId}=await call('Target.attachToTarget',{targetId,flatten:true});
 const evaluate=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true},sessionId)).result.value;
 const until=async predicate=>{for(let i=0;i<80;i++){try{if(await predicate())return;}catch{}await new Promise(r=>setTimeout(r,100));}throw Error('remote fixture did not reach the expected state');};
 const browser=await chromium.launch({headless:true});let otherBrowser;
 try{
  await until(()=>evaluate("document.title==='TeamX handoff test'"));
  const context=await browser.newContext({viewport:{width:1600,height:1000}}),page=await context.newPage(),errors=[];
  page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(15000);
  await page.goto(endpoint);await page.locator(`[data-room-key*='${fixture.room.room_instance}'] .room-choice`).click();
  await page.waitForFunction(()=>!document.querySelector('#message-input').disabled);
  const open=async p=>{await p.locator('#room-menu-label').click();await p.locator('#conversation-open-environment').click();await p.locator('#environment-status').filter({hasText:/已连接|其他页面正在接管/}).waitFor();};
  await open(page);
  const clickRemote=async (selector,waitFocus=true)=>{
   const point=await evaluate(`(()=>{const r=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return {x:screenX+(outerWidth-innerWidth)/2+r.x+r.width/2,y:screenY+outerHeight-innerHeight+r.y+r.height/2}})()`);
   const canvas=page.frameLocator('#environment-screen iframe').locator('canvas');
   const native=await canvas.evaluate(c=>({width:c.width,height:c.height})),box=await canvas.boundingBox();
   await canvas.click({position:{x:point.x*box.width/native.width,y:point.y*box.height/native.height}});
   if(waitFocus && (selector==='#username'||selector==='#password')) await until(()=>evaluate(`document.activeElement.id===${JSON.stringify(selector.slice(1))}`));
  };
  await clickRemote('#username',false);await page.keyboard.type('blocked');
  assert.equal(await evaluate("document.querySelector('#username').value"),'');
  await page.locator('#environment-control').click();
  await page.locator('#environment-status').filter({hasText:'可直接输入'}).waitFor();
  otherBrowser=await chromium.launch({headless:true});const other=await otherBrowser.newPage();await other.goto(endpoint);
  await other.locator(`[data-room-key*='${fixture.room.room_instance}'] .room-choice`).click();await other.waitForFunction(()=>!document.querySelector('#message-input').disabled);
  await open(other);assert.equal(await other.locator('#environment-control').isDisabled(),true);await other.close();await otherBrowser.close();
  await page.bringToFront();
  await clickRemote('#username');await page.keyboard.type('demo-user');
  await until(()=>evaluate("document.querySelector('#username').value==='demo-user'"));
  await clickRemote('#password');
  const viewer=page.frameLocator('#environment-screen iframe');
  await viewer.locator('#keyboard-toggle').click();await viewer.locator('#keyboard').fill('demo-pass-4x');
  await until(()=>evaluate("document.querySelector('#password').value==='demo-pass-4x'"));
  await viewer.locator('#keyboard').press('Backspace');
  await until(()=>evaluate("document.querySelector('#password').value==='demo-pass-4'"));
  await viewer.locator('#keyboard').fill('2');
  await until(()=>evaluate("document.querySelector('#password').value==='demo-pass-42'"));
  assert.equal(await evaluate("document.querySelector('#username').value"),'demo-user');
  assert.equal(await evaluate("document.querySelector('#password').value"),'demo-pass-42');
  assert.equal(await viewer.locator('#keyboard').inputValue(),'');
  await clickRemote('#login');await until(()=>evaluate("document.title==='Signed in'"));
  const dir=process.env.TEAMX_ENVIRONMENT_ARTIFACTS;if(dir){fs.mkdirSync(dir,{recursive:true});await page.screenshot({path:path.join(dir,'handoff-signed-in.png')});}
  await page.locator('#environment-control').click();await page.locator('#environment-status').filter({hasText:'已交还 Agent'}).waitFor();
  assert.equal(await evaluate("document.title==='Signed in'"),true);assert.deepEqual(errors,[]);
  console.log(JSON.stringify({status:'passed',scope:'real AIO VNC input + dummy HTTP login cookie + controlled Agent continuation; no real model or account',checks:['view mode rejects typing','owned takeover enables mouse and keyboard','second page cannot take control','same browser signs in with dummy credentials','finish returns to view and resumes prior scheduling'],errors}));
 }finally{await otherBrowser?.close();await browser.close();await call('Target.closeTarget',{targetId});socket.close();}
})().catch(e=>{console.error(e.stack);process.exit(1);});
